cat > src/status-codes.js <<'EOF'
import { STATUS_CODES as NODE_STATUS_CODES } from 'node:http';

/**
 * Frozen lookup table of HTTP status codes to their standard reason phrases,
 * e.g. STATUS_CODES[404] === 'Not Found'.
 *
 * Sourced from Node's built-in table, which tracks the IANA HTTP Status Code
 * Registry, so it stays current with Node upgrades.
 */
export const STATUS_CODES = Object.freeze(
  Object.fromEntries(
    Object.entries(NODE_STATUS_CODES).map(([code, phrase]) => [Number(code), phrase]),
  ),
);

/**
 * Returns the reason phrase for a status code, or undefined if it is not a
 * registered code. Accepts numbers or numeric strings.
 */
export function getReasonPhrase(code) {
  const n = Number(code);
  return Number.isInteger(n) ? STATUS_CODES[n] : undefined;
}

/** Returns true if the code is in the table. */
export function isKnownStatus(code) {
  return getReasonPhrase(code) !== undefined;
}
EOF
cat > src/server.js <<'EOF'
import { createServer } from 'node:http';
import { pathToFileURL } from 'node:url';
import { STATUS_CODES, getReasonPhrase } from './status-codes.js';

function sendJson(res, status, body) {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

function sendError(res, status) {
  sendJson(res, status, { error: getReasonPhrase(status) });
}

export function handler(req, res) {
  const { pathname } = new URL(req.url, 'http://localhost');

  if (req.method !== 'GET' && req.method !== 'HEAD') {
    res.setHeader('Allow', 'GET, HEAD');
    return sendError(res, 405);
  }

  if (pathname === '/health') {
    return sendJson(res, 200, { status: 'ok' });
  }

  if (pathname === '/status-codes') {
    return sendJson(res, 200, STATUS_CODES);
  }

  const match = pathname.match(/^\/status-codes\/(\d{3})$/);
  if (match) {
    const code = Number(match[1]);
    const phrase = getReasonPhrase(code);
    return phrase
      ? sendJson(res, 200, { code, phrase })
      : sendError(res, 404);
  }

  return sendError(res, 404);
}

export function createAppServer() {
  return createServer(handler);
}

// Start listening only when run directly (not when imported by tests).
if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const port = Number(process.env.PORT) || 3000;
  const server = createAppServer();
  server.listen(port, () => {
    console.log(`Listening on http://localhost:${port}`);
  });

  const shutdown = () => server.close(() => process.exit(0));
  process.on('SIGINT', shutdown);
  process.on('SIGTERM', shutdown);
}
EOF
cat > test/status-codes.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { STATUS_CODES, getReasonPhrase, isKnownStatus } from '../src/status-codes.js';

test('maps common codes to standard reason phrases', () => {
  assert.equal(STATUS_CODES[200], 'OK');
  assert.equal(STATUS_CODES[201], 'Created');
  assert.equal(STATUS_CODES[301], 'Moved Permanently');
  assert.equal(STATUS_CODES[404], 'Not Found');
  assert.equal(STATUS_CODES[418], "I'm a Teapot");
  assert.equal(STATUS_CODES[500], 'Internal Server Error');
});

test('table is frozen', () => {
  assert.ok(Object.isFrozen(STATUS_CODES));
});

test('getReasonPhrase accepts numbers and numeric strings', () => {
  assert.equal(getReasonPhrase(404), 'Not Found');
  assert.equal(getReasonPhrase('503'), 'Service Unavailable');
});

test('unknown or invalid codes return undefined', () => {
  assert.equal(getReasonPhrase(299), undefined);
  assert.equal(getReasonPhrase('abc'), undefined);
  assert.equal(getReasonPhrase(200.5), undefined);
  assert.equal(isKnownStatus(999), false);
  assert.equal(isKnownStatus(204), true);
});
EOF
cat > test/server.test.js <<'EOF'
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { createAppServer } from '../src/server.js';

let server;
let base;

before(async () => {
  server = createAppServer();
  await new Promise((resolve) => server.listen(0, resolve));
  base = `http://localhost:${server.address().port}`;
});

after(() => new Promise((resolve) => server.close(resolve)));

test('GET /health', async () => {
  const res = await fetch(`${base}/health`);
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { status: 'ok' });
});

test('GET /status-codes returns the full table', async () => {
  const body = await (await fetch(`${base}/status-codes`)).json();
  assert.equal(body['404'], 'Not Found');
});

test('GET /status-codes/:code returns a single entry', async () => {
  const res = await fetch(`${base}/status-codes/429`);
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { code: 429, phrase: 'Too Many Requests' });
});

test('unknown code returns 404', async () => {
  const res = await fetch(`${base}/status-codes/299`);
  assert.equal(res.status, 404);
  assert.deepEqual(await res.json(), { error: 'Not Found' });
});

test('non-GET returns 405 with Allow header', async () => {
  const res = await fetch(`${base}/health`, { method: 'POST' });
  assert.equal(res.status, 405);
  assert.equal(res.headers.get('allow'), 'GET, HEAD');
});
EOF
npm test 2>&1 | tail -20

